//! Integration tests against the fixtures in `tests/fixtures` (generated by
//! `tests/fixtures/generate.py`). Run with `cargo test --no-default-features`.

use std::path::PathBuf;

use pdf_preflight::fonts::Embedding;
use pdf_preflight::pages::BoxSource;
use pdf_preflight::{Document, Limits, OpenOptions, PreflightError, Value};

fn fixture(name: &str) -> String {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../tests/fixtures").join(name).to_string_lossy().into_owned()
}

fn open(name: &str) -> Document {
    Document::open(&fixture(name), &OpenOptions::default()).unwrap_or_else(|e| panic!("{name}: {e}"))
}

fn open_with(name: &str, limits: Limits) -> Result<Document, PreflightError> {
    Document::open(&fixture(name), &OpenOptions { limits, ..Default::default() })
}

fn issue_codes(issues: &[pdf_preflight::Issue]) -> Vec<&'static str> {
    issues.iter().map(|i| i.code).collect()
}

fn approx(a: f64, b: f64) -> bool {
    (a - b).abs() < 0.01
}

// ---------------------------------------------------------------------------
// Document structure
// ---------------------------------------------------------------------------

#[test]
fn single_page_a4() {
    let doc = open("single_a4.pdf");
    assert_eq!(doc.page_count(), 1);
    let s = doc.structure();
    assert_eq!(s.version, "1.4");
    assert!(s.encryption.is_none());
    assert_eq!(s.info.get("Title").map(String::as_str), Some("Einseitiges A4 – Prüfdatei"));
    assert!(s.issues.is_empty(), "{:?}", s.issues);

    let info = doc.document_info_value();
    assert_eq!(
        info.get("info").and_then(|i| i.get("CreationDateIso")).and_then(Value::as_str),
        Some("2026-01-01T12:00:00+01:00")
    );

    let g = doc.page_geometry(1).unwrap();
    let crop = g.get("CropBox").unwrap();
    let (w, h) = g.display_size_mm(crop);
    assert!(approx(w, 210.0) && approx(h, 297.0), "{w} x {h}");
    assert_eq!(g.rotation, 0);
}

#[test]
fn page_numbers_are_one_based() {
    let doc = open("single_a4.pdf");
    assert!(doc.page_geometry(1).is_ok());
    for page in [0, 2, -1] {
        assert_eq!(doc.page_geometry(page).unwrap_err(), PreflightError::PageOutOfRange { page, page_count: 1 });
        assert!(doc.page_content(page).is_err());
    }
}

#[test]
fn multipage_with_inherited_attributes() {
    let doc = open("multipage.pdf");
    assert_eq!(doc.page_count(), 4);

    let expected = [(1, 210.0, 297.0), (2, 297.0, 210.0), (3, 148.0, 210.0)];
    for (page, w, h) in expected {
        let g = doc.page_geometry(page).unwrap();
        let (dw, dh) = g.display_size_mm(g.get("MediaBox").unwrap());
        assert!(approx(dw, w) && approx(dh, h), "page {page}: {dw} x {dh}");
    }

    let p1 = doc.page_geometry(1).unwrap();
    assert_eq!(p1.get("MediaBox").unwrap().source, BoxSource::Inherited);
    let p2 = doc.page_geometry(2).unwrap();
    assert_eq!(p2.get("MediaBox").unwrap().source, BoxSource::Page);

    // Page 4 inherits MediaBox (A3) and CropBox from an intermediate node.
    let p4 = doc.page_geometry(4).unwrap();
    assert_eq!(p4.get("MediaBox").unwrap().source, BoxSource::Inherited);
    assert_eq!(p4.get("CropBox").unwrap().source, BoxSource::Inherited);
    assert!(approx(p4.get("MediaBox").unwrap().rect.width(), 841.89));
    assert_eq!(p4.get("TrimBox").unwrap().source, BoxSource::Default("CropBox"));
    assert!(approx(p4.get("TrimBox").unwrap().rect.width(), 821.89));
}

#[test]
fn rotation() {
    let doc = open("rotated.pdf");
    let rotations: Vec<i32> = (1..=6).map(|p| doc.page_geometry(p).unwrap().rotation).collect();
    // 90, 180, 270, -90 -> 270, 45 (invalid) -> 0, inherited 90
    assert_eq!(rotations, vec![90, 180, 270, 270, 0, 90]);

    let p1 = doc.page_geometry(1).unwrap();
    let (w, h) = p1.display_size_mm(p1.get("CropBox").unwrap());
    assert!(approx(w, 297.0) && approx(h, 210.0));
    assert_eq!(p1.to_value().get("orientation").and_then(Value::as_str), Some("landscape"));

    let p5 = doc.page_geometry(5).unwrap();
    assert_eq!(issue_codes(&p5.issues), vec!["invalid_rotation"]);
}

#[test]
fn page_boxes_defined_and_derived() {
    let doc = open("boxes.pdf");

    // Business card: 85 x 55 trim, 3 mm bleed on each side.
    let g = doc.page_geometry(1).unwrap();
    let trim = g.get("TrimBox").unwrap();
    let bleed = g.get("BleedBox").unwrap();
    assert_eq!(trim.source, BoxSource::Page);
    assert_eq!(g.get("CropBox").unwrap().source, BoxSource::Default("MediaBox"));
    let (tw, th) = g.display_size_mm(trim);
    assert!(approx(tw, 85.0) && approx(th, 55.0), "{tw} x {th}");
    let bleed_margin_mm = (trim.rect.x0 - bleed.rect.x0) * pdf_preflight::pages::PT_TO_MM;
    assert!(approx(bleed_margin_mm, 3.0), "{bleed_margin_mm}");

    // Only MediaBox defined: everything else derived.
    let g = doc.page_geometry(2).unwrap();
    for name in ["BleedBox", "TrimBox", "ArtBox"] {
        assert!(!g.get(name).unwrap().is_defined());
        assert_eq!(g.get(name).unwrap().source, BoxSource::Default("CropBox"));
    }

    // Reversed corners are normalised; boxes beyond the MediaBox are clipped.
    let g = doc.page_geometry(3).unwrap();
    let trim = g.get("TrimBox").unwrap();
    assert!(trim.rect.x0 < trim.rect.x1 && trim.rect.y0 < trim.rect.y1);
    let bleed = g.get("BleedBox").unwrap();
    assert!(bleed.rect.width() > bleed.effective.width());
    assert!(issue_codes(&g.issues).contains(&"box_exceeds_media_box"));

    // A TrimBox on a Pages node is not inherited.
    let g = doc.page_geometry(4).unwrap();
    assert_eq!(g.get("TrimBox").unwrap().source, BoxSource::Default("CropBox"));
    assert!(issue_codes(&g.issues).contains(&"non_inheritable_box_on_pages_node"));

    // UserUnit 2 doubles the physical size: A4 numbers -> A2.
    let g = doc.page_geometry(5).unwrap();
    assert_eq!(g.user_unit, 2.0);
    let (w, h) = g.display_size_mm(g.get("MediaBox").unwrap());
    assert!(approx(w, 420.0) && approx(h, 594.0), "{w} x {h}");

    // Invalid and missing MediaBox -> fallback with issue.
    for page in [6, 7] {
        let g = doc.page_geometry(page).unwrap();
        assert_eq!(g.get("MediaBox").unwrap().source, BoxSource::Fallback);
        assert!(issue_codes(&g.issues).contains(&"missing_media_box"));
    }
}

