fn font<'a>(content: &'a pdf_preflight::content::PageContent, name: &str) -> &'a pdf_preflight::content::FontUsage {
    content.fonts.iter().find(|f| f.info.name == name).unwrap_or_else(|| panic!("font {name} not found"))
}

#[test]
fn fonts_embedding_status() {
    let doc = open("fonts.pdf");
    let c = doc.page_content(1).unwrap();
    assert!(c.complete);

    let helv = font(&c, "Helvetica");
    assert_eq!(helv.info.embedding, Embedding::NotEmbedded);
    assert!(helv.info.standard14 && helv.used && helv.visible);

    let tt = font(&c, "StubSans");
    assert_eq!(tt.info.embedding, Embedding::Embedded);
    assert!(tt.info.subset);
    assert_eq!(tt.info.font_file, Some("FontFile2"));
    assert_eq!(tt.info.program_format, Some("truetype"));

    let cid = font(&c, "StubCID");
    assert_eq!(cid.info.font_type, "Type0");
    assert_eq!(cid.info.descendant_type.as_deref(), Some("CIDFontType0"));
    assert_eq!(cid.info.embedding, Embedding::Embedded);
    assert_eq!(cid.info.program_format, Some("cff"));

    let type3 = c.fonts.iter().find(|f| f.info.font_type == "Type3").unwrap();
    assert_eq!(type3.info.embedding, Embedding::Embedded);

    // Declared in the resources but never used to show text.
    let times = font(&c, "Times-Roman");
    assert!(!times.used);

    // Only used with text rendering mode 3 (invisible).
    let invisible = font(&c, "Courier-Bold");
    assert!(invisible.used && !invisible.visible);
}

#[test]
fn fonts_in_nested_forms() {
    let doc = open("fonts.pdf");
    let c = doc.page_content(2).unwrap();
    let courier = font(&c, "Courier");
    assert!(courier.used);
    assert!(courier.contexts.contains("form"));
}

#[test]
fn broken_font_embeddings() {
    let doc = open("fonts.pdf");
    let c = doc.page_content(3).unwrap();
    assert_eq!(font(&c, "Dangling").info.embedding, Embedding::Invalid);
    assert_eq!(font(&c, "EmptyProgram").info.embedding, Embedding::Invalid);
    let wrong = font(&c, "WrongProgram");
    assert_eq!(wrong.info.embedding, Embedding::Embedded);
    assert!(!wrong.info.problems.is_empty());
}

#[test]
fn fonts_from_ext_g_state_annotations_and_patterns() {
    let doc = open("fonts.pdf");
    let c = doc.page_content(4).unwrap();
    assert!(font(&c, "Helvetica-Bold").used, "font selected via gs operator");
    let annot = font(&c, "Helvetica-Oblique");
    assert!(annot.used && annot.contexts.contains("annotation"));
    assert!(c.fonts.iter().all(|f| f.info.name != "Symbol"), "non-printing annotation must be ignored");

    let c = doc.page_content(5).unwrap();
    assert!(font(&c, "Times-Bold").contexts.contains("pattern"));
    assert_eq!(issue_codes(&c.issues), vec!["font_resource_missing"]);
}

#[test]
fn document_level_font_summary() {
    let doc = open("fonts.pdf");
    let analysis = doc.analyze_value();
    let Some(Value::List(fonts)) = analysis.get("fonts") else { panic!("fonts missing") };
    let courier = fonts.iter().find(|f| f.get("name").and_then(Value::as_str) == Some("Courier")).unwrap();
    assert_eq!(courier.get("pages"), Some(&Value::List(vec![Value::Int(2)])));
    assert_eq!(analysis.get("analysis_complete"), Some(&Value::Bool(true)));
}

// ---------------------------------------------------------------------------
// Nested forms, recursion and limits
// ---------------------------------------------------------------------------

#[test]
fn nested_forms_and_cycles() {
    let doc = open("nested_forms.pdf");

    let deep = doc.page_content(1).unwrap();
    assert!(deep.complete);
    assert!(font(&deep, "Courier").used);

    let cycle = doc.page_content(2).unwrap();
    assert!(issue_codes(&cycle.issues).contains(&"xobject_cycle"));

    let too_deep = doc.page_content(3).unwrap();
    assert!(!too_deep.complete, "nesting beyond the limit must mark the page incomplete");
    assert!(issue_codes(&too_deep.issues).contains(&"limit_exceeded"));

    // A form drawn 1000 times is interpreted once.
    let reused = doc.page_content(4).unwrap();
    assert!(reused.complete);
    assert!(reused.operations < 10_000, "{}", reused.operations);

    let inherited = doc.page_content(5).unwrap();
    assert!(font(&inherited, "Courier").used, "form without /Resources uses the page resources");
}

#[test]
fn operation_limit_marks_page_incomplete() {
    let limits = Limits { max_operations_per_page: 100, ..Limits::default() };
    let doc = open_with("nested_forms.pdf", limits).unwrap();
    let c = doc.page_content(4).unwrap();
    assert!(!c.complete);
    assert!(issue_codes(&c.issues).contains(&"limit_exceeded"));
}

#[test]
fn content_results_are_cached() {
    let doc = open("fonts.pdf");
    let a = doc.page_content(1).unwrap();
    let b = doc.page_content(1).unwrap();
    assert!(std::rc::Rc::ptr_eq(&a, &b));
}

