#[test]
fn object_streams() {
    let doc = open("objstm.pdf");
    assert_eq!(doc.page_count(), 2);
    assert_eq!(doc.structure().guard.verified, 2, "object stream and xref stream are pre-checked");
    assert_eq!(doc.structure().info.get("Title").map(String::as_str), Some("Object streams"));
    assert!(font(&doc.page_content(2).unwrap(), "Helvetica").used);
}

#[test]
fn pdfx_identification_is_not_validation() {
    let doc = open("pdfx_declared.pdf");
    let info = doc.document_info_value();
    let pdfx = info.get("pdfx").unwrap();
    assert_eq!(pdfx.get("declared"), Some(&Value::Bool(true)));
    assert_eq!(pdfx.get("version").and_then(Value::as_str), Some("PDF/X-4"));
    assert_eq!(pdfx.get("version_xmp").and_then(Value::as_str), Some("PDF/X-4"));
    assert_eq!(pdfx.get("has_pdfx_output_intent"), Some(&Value::Bool(true)));
    assert_eq!(pdfx.get("validated"), Some(&Value::Bool(false)));
    let oi = &doc.structure().output_intents[0];
    assert_eq!(oi.output_condition_identifier.as_deref(), Some("FOGRA39"));
}

