#[test]
fn encrypted_with_empty_user_password() {
    let doc = open("encrypted_empty_password.pdf");
    let enc = doc.structure().encryption.as_ref().expect("encryption detected");
    assert_eq!((enc.v, enc.r, enc.length), (Some(2), Some(3), Some(128)));
    assert_eq!(doc.structure().info.get("Title").map(String::as_str), Some("Verschlüsselt"));
    assert!(font(&doc.page_content(1).unwrap(), "Helvetica").used, "content stream decrypted");
}

#[test]
fn encrypted_with_user_password() {
    let err = Document::open(&fixture("encrypted_user_password.pdf"), &OpenOptions::default()).err();
    assert_eq!(err, Some(PreflightError::PasswordRequired));
    let wrong = OpenOptions { password: "wrong".into(), ..Default::default() };
    assert_eq!(
        Document::open(&fixture("encrypted_user_password.pdf"), &wrong).err(),
        Some(PreflightError::PasswordRequired)
    );
    let right = OpenOptions { password: "secret".into(), ..Default::default() };
    let doc = Document::open(&fixture("encrypted_user_password.pdf"), &right).unwrap();
    assert_eq!(doc.page_count(), 1);
}

