#[test]
fn damaged_but_recoverable() {
    for (name, code) in [
        ("damaged/bad_xref_offsets.pdf", "startxref_invalid"),
        ("damaged/header_offset.pdf", "header_offset"),
        ("damaged/no_eof.pdf", "eof_marker_missing"),
    ] {
        let doc = open(name);
        assert_eq!(doc.page_count(), 2, "{name}");
        assert_eq!(issue_codes(&doc.structure().issues), vec![code], "{name}");
        assert!(doc.page_content(2).unwrap().complete);
    }
}

#[test]
fn damaged_beyond_recovery() {
    for name in ["damaged/empty.pdf", "damaged/not_a_pdf.pdf", "damaged/header_only.pdf", "damaged/truncated.pdf"] {
        let err = Document::open(&fixture(name), &OpenOptions::default()).err();
        assert!(matches!(err, Some(PreflightError::InvalidPdf(_))), "{name}: {err:?}");
    }
}

#[test]
fn missing_file() {
    let err = Document::open("/nonexistent/file.pdf", &OpenOptions::default()).err();
    assert!(matches!(err, Some(PreflightError::Io(_))));
}

#[test]
fn file_size_limit() {
    let limits = Limits { max_file_size: 100, ..Limits::default() };
    let err = open_with("single_a4.pdf", limits).err();
    assert!(matches!(err, Some(PreflightError::FileTooLarge { limit: 100, .. })));
}

#[test]
fn content_stream_bomb() {
    // 64 MiB of decoded content against a 1 MiB limit.
    let limits = Limits { max_stream_size: 1 << 20, ..Limits::default() };
    let doc = open_with("bomb_content_stream.pdf", limits).unwrap();
    let c = doc.page_content(1).unwrap();
    assert!(!c.complete);
    assert!(issue_codes(&c.issues).contains(&"limit_exceeded"));
}

#[test]
fn total_decoded_budget() {
    let limits = Limits { max_total_decoded: 1 << 20, ..Limits::default() };
    let doc = open_with("bomb_content_stream.pdf", limits).unwrap();
    let c = doc.page_content(1).unwrap();
    assert!(!c.complete);
    assert!(c.issues[0].message.contains("max_total_decoded"), "{:?}", c.issues);
}

#[test]
fn object_stream_bomb_rejected_before_parsing() {
    let limits = Limits { max_stream_size: 1 << 20, ..Limits::default() };
    let err = open_with("bomb_object_stream.pdf", limits).err();
    assert!(matches!(err, Some(PreflightError::LimitExceeded { limit: "max_stream_size", .. })), "{err:?}");
}

#[test]
fn object_and_page_limits() {
    let err = open_with("multipage.pdf", Limits { max_pages: 3, ..Limits::default() }).err();
    assert!(matches!(err, Some(PreflightError::LimitExceeded { limit: "max_pages", .. })));
    let err = open_with("multipage.pdf", Limits { max_objects: 3, ..Limits::default() }).err();
    assert!(matches!(err, Some(PreflightError::LimitExceeded { limit: "max_objects", .. })));
}

/// Mutates every fixture in many ways and checks that the library never
/// panics and always returns either a document or an error.
#[test]
fn mutated_inputs_do_not_panic() {
    let files = [
        "single_a4.pdf",
        "fonts.pdf",
        "objstm.pdf",
        "nested_forms.pdf",
        "encrypted_empty_password.pdf",
        "boxes.pdf",
        "colors.pdf",
        "images.pdf",
    ];
    let mut seed: u64 = 0x2545_F491_4F6C_DD1D;
    let mut next = move || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    let limits = Limits { max_analysis_time_ms: 2_000, ..Limits::default() };
    for round in 0..1200 {
        let original = std::fs::read(fixture(files[round % files.len()])).unwrap();
        let mut data = original.clone();
        for _ in 0..(1 + next() % 6) {
            let pos = (next() as usize) % data.len().max(1);
            match next() % 4 {
                0 => data[pos] = next() as u8,
                1 => data.truncate(pos.max(1)),
                2 => data[pos] = b"0123456789 R/<>[]()obj"[(next() % 22) as usize],
                _ => {
                    let end = (pos + (next() % 64) as usize).min(data.len());
                    data.drain(pos..end);
                }
            }
            if data.is_empty() {
                data.push(b'%');
            }
        }
        let result = std::panic::catch_unwind(|| {
            let options = OpenOptions { limits: limits.clone(), ..Default::default() };
            if let Ok(doc) = Document::from_bytes(data, &options) {
                let _ = doc.analyze_value().to_json();
            }
        });
        assert!(result.is_ok(), "panic in round {round}");
    }
}

