#[test]
fn color_classification_per_page() {
    let doc = open("colors.pdf");
    let expected = [
        (1, "grayscale"),  // DeviceGray, neutral RGB, K-only CMYK, gray text
        (2, "color"),      // RGB red
        (3, "color"),      // CMYK cyan
        (4, "color"),      // spot colour
        (5, "grayscale"),  // Separation Black, DeviceN with Black only
        (6, "color"),      // colour inside a nested form
        (7, "color"),      // form inherits the page's fill colour
        (8, "grayscale"),  // ICC N=3 neutral, ICC N=1, Lab a=b=0
        (9, "grayscale"),  // Indexed with gray palette
        (10, "grayscale"), // blank page
        (11, "color"),     // RGB gradient red -> blue
        (12, "grayscale"), // RGB gradient black -> white
        (13, "color"),     // coloured tiling pattern
        (14, "grayscale"), // RGB declared but not used
        (15, "grayscale"), // invisible red text
        (16, "unknown"),   // sampled function cannot be evaluated
        (17, "grayscale"), // uncoloured pattern painted gray
    ];
    for (page, class) in expected {
        let c = doc.page_content(page).unwrap();
        assert_eq!(c.colors.classification(c.complete), class, "page {page}");
    }
    let blank = doc.page_content(10).unwrap();
    assert_eq!(blank.colors.to_value(true).get("painted"), Some(&Value::Bool(false)));
}

#[test]
fn declared_versus_used_color_spaces() {
    let doc = open("colors.pdf");
    let c = doc.page_content(14).unwrap();
    let declared: Vec<&str> = c.colors.declared.iter().map(|(_, cs)| cs.category()).collect();
    assert_eq!(declared, vec!["rgb", "spot"]);
    let used: Vec<&str> = c.colors.used.iter().map(|u| u.cs.category()).collect();
    assert_eq!(used, vec!["gray"]);
    assert!(c.colors.spot_colors.is_empty(), "declared spot colour is not used");
}

#[test]
fn spot_colors() {
    let doc = open("colors.pdf");
    let c = doc.page_content(4).unwrap();
    assert_eq!(c.colors.spot_colors.iter().collect::<Vec<_>>(), vec!["HKS 13 K"]);
    let analysis = doc.analyze_value();
    let summary = analysis.get("colors").unwrap();
    assert_eq!(summary.get("spot_colors"), Some(&Value::List(vec![Value::Str("HKS 13 K".into())])));
    assert_eq!(summary.get("unknown_pages"), Some(&Value::List(vec![Value::Int(16)])));
}

#[test]
fn incomplete_analysis_is_never_classified_grayscale() {
    let limits = Limits { max_operations_per_page: 3, ..Limits::default() };
    let doc = open_with("colors.pdf", limits).unwrap();
    let c = doc.page_content(1).unwrap();
    assert!(!c.complete);
    assert_eq!(c.colors.classification(c.complete), "unknown");
}

// ---------------------------------------------------------------------------
// Images
// ---------------------------------------------------------------------------

fn dpi(p: &pdf_preflight::images::Placement) -> (i64, i64) {
    (p.dpi_x.round() as i64, p.dpi_y.round() as i64)
}

#[test]
fn image_resolution_and_placements() {
    let doc = open("images.pdf");

    let p1 = doc.page_content(1).unwrap();
    assert_eq!(p1.images.len(), 1);
    let img = &p1.images[0];
    assert_eq!((img.image.width, img.image.height), (300, 300));
    assert_eq!(img.image.color_space.as_ref().unwrap().family.name(), "DeviceRGB");
    assert_eq!(img.image.bits_per_component, Some(8));
    assert_eq!(img.image.compression, "flate");
    assert_eq!(dpi(img), (300, 300));
    assert!(img.on_page);

    // Same image at two sizes -> two effective resolutions.
    let p2 = doc.page_content(2).unwrap();
    let mut dpis: Vec<_> = p2.images.iter().map(dpi).collect();
    dpis.sort();
    assert_eq!(dpis, vec![(150, 150), (300, 300)]);

    // Non-uniform scaling
    assert_eq!(dpi(&doc.page_content(3).unwrap().images[0]), (50, 100));

    // Scaled form and 90° rotation both give 300 dpi; aggregated.
    let p4 = doc.page_content(4).unwrap();
    assert_eq!(p4.images.len(), 1);
    assert_eq!(dpi(&p4.images[0]), (300, 300));
    assert_eq!(p4.images[0].count, 2);
    assert!(p4.images[0].contexts.contains("form"));

    // Placed outside the page
    assert!(!doc.page_content(9).unwrap().images[0].on_page);

    // Inline image
    let inline = &doc.page_content(10).unwrap().images[0];
    assert!(inline.image.inline);
    assert_eq!((inline.image.width, inline.image.height), (2, 2));
}

#[test]
fn image_color_classification() {
    let doc = open("images.pdf");
    let expected = [
        (1, "grayscale"), // neutral RGB pixels
        (3, "color"),
        (5, "color"),      // gray image + red stencil mask
        (6, "grayscale"),  // neutral RGB JPEG (decoded)
        (7, "color"),      // coloured RGB JPEG
        (8, "grayscale"),  // 1-component JPEG
        (10, "color"),     // inline RGB
        (11, "grayscale"), // indexed: red palette entry unused
        (12, "grayscale"), // 1-bit gray
        (13, "grayscale"), // CMYK with K only
    ];
    for (page, class) in expected {
        let c = doc.page_content(page).unwrap();
        assert_eq!(c.colors.classification(c.complete), class, "page {page}");
    }
    let mask = &doc.page_content(5).unwrap().images[1];
    assert!(mask.image.image_mask);
}

#[test]
fn color_check_pixel_limit() {
    let limits = Limits { max_color_check_pixels: 1000, ..Limits::default() };
    let doc = open_with("images.pdf", limits).unwrap();
    let c = doc.page_content(1).unwrap();
    assert_eq!(c.colors.classification(c.complete), "unknown");
    assert!(c.colors.reasons[0].contains("max_color_check_pixels"), "{:?}", c.colors.reasons);
    // Small images are still checked.
    let c = doc.page_content(13).unwrap();
    assert_eq!(c.colors.classification(c.complete), "grayscale");
}

#[test]
fn image_placement_limit() {
    let limits = Limits { max_image_placements: 1, ..Limits::default() };
    let doc = open_with("images.pdf", limits).unwrap();
    let c = doc.page_content(2).unwrap();
    assert_eq!(c.images.len(), 1);
    assert!(!c.complete);
}

// ---------------------------------------------------------------------------
// Large documents
// ---------------------------------------------------------------------------

/// Builds a PDF with `pages` pages in memory (shared font and form).
fn large_pdf(pages: usize) -> Vec<u8> {
    let mut out = b"%PDF-1.7\n".to_vec();
    let mut offsets = Vec::new();
    let mut obj = |out: &mut Vec<u8>, body: String| {
        offsets.push(out.len());
        out.extend_from_slice(format!("{} 0 obj\n{body}\nendobj\n", offsets.len()).as_bytes());
    };
    // 1: catalog, 2: pages, 3: font, 4: form, then content+page pairs
    obj(&mut out, "<< /Type /Catalog /Pages 2 0 R >>".into());
    let kids: String = (0..pages).map(|i| format!("{} 0 R ", 6 + 2 * i)).collect();
    obj(&mut out, format!("<< /Type /Pages /Kids [{kids}] /Count {pages} /MediaBox [0 0 595.276 841.89] >>"));
    obj(&mut out, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>".into());
    let form = "BT /F1 8 Tf (form) Tj ET";
    obj(
        &mut out,
        format!(
            "<< /Type /XObject /Subtype /Form /BBox [0 0 100 100] /Resources << /Font << /F1 3 0 R >> >> /Length {} >>\nstream\n{form}\nendstream",
            form.len()
        ),
    );
    for i in 0..pages {
        let content = format!("BT /F1 12 Tf 72 700 Td (Page {i}) Tj ET q /X Do Q");
        obj(&mut out, format!("<< /Length {} >>\nstream\n{content}\nendstream", content.len()));
        obj(
            &mut out,
            format!(
                "<< /Type /Page /Parent 2 0 R /Contents {} 0 R /Resources << /Font << /F1 3 0 R >> /XObject << /X 4 0 R >> >> >>",
                5 + 2 * i
            ),
        );
    }
    let xref_pos = out.len();
    out.extend_from_slice(format!("xref\n0 {}\n0000000000 65535 f \n", offsets.len() + 1).as_bytes());
    for off in &offsets {
        out.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
    }
    out.extend_from_slice(
        format!("trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{xref_pos}\n%%EOF\n", offsets.len() + 1).as_bytes(),
    );
    out
}

#[test]
fn large_document() {
    let data = large_pdf(5_000);
    let doc = Document::from_bytes(data, &OpenOptions::default()).unwrap();
    assert_eq!(doc.page_count(), 5_000);
    assert!(doc.structure().issues.is_empty(), "{:?}", doc.structure().issues);
    let analysis = doc.analyze_value();
    assert_eq!(analysis.get("analysis_complete"), Some(&Value::Bool(true)));
    let Some(Value::List(fonts)) = analysis.get("fonts") else { panic!() };
    assert_eq!(fonts.len(), 1, "one shared font object");
    let Some(Value::List(pages)) = fonts[0].get("pages") else { panic!() };
    assert_eq!(pages.len(), 5_000);
}

