/// Timing breakdown for a large file given in PDF_BENCH_FILE (not run by default).
#[test]
#[ignore = "benchmark helper: PDF_BENCH_FILE=/path/file.pdf cargo test --release -- --ignored open_breakdown --nocapture"]
fn open_breakdown() {
    let Ok(path) = std::env::var("PDF_BENCH_FILE") else { return };
    let t = std::time::Instant::now();
    let data = std::fs::read(&path).unwrap();
    let read = t.elapsed();
    let t = std::time::Instant::now();
    let report = pdf_preflight::guard::scan(&data, 256 << 20).unwrap();
    let guard = t.elapsed();
    let t = std::time::Instant::now();
    let doc = Document::from_bytes(data, &OpenOptions::default()).unwrap();
    let open = t.elapsed();
    println!("read={read:?} guard={guard:?} ({report:?}) from_bytes(incl. guard)={open:?} pages={}", doc.page_count());
}
